研究五：利用紅外線遙控電器用品 
我們發現我們利用紅外線製作的系統，受到光線很大的干擾。於是我們上網尋找解決方式，發現平常使用的遙控器，也是紅外線。於是我們利用紅外線的特定頻率38KHz，研究紅外線38KHz 的遙控電器與警戒線，大大降低光線的干擾。 
紅外線接收38KHz 解碼 
Protocol 代表 紅外線協定種類 
irCode 代表 紅外線訊號的編碼 
bits 代表 幾個位元 

#include <IRremote.h> 
 // 引用 IRRemote 函式庫 
const int irReceiverPin = 2; 
// 紅外線接收器 OUTPUT 訊號接在 pin 2 
IRrecv irrecv(irReceiverPin); // 定義 IRrecv 物件來接收紅外線訊號 
decode_results results; 
// 解碼結果將放在 decode_results 結構的 result 變數裏 
void setup() 
{ 
 Serial.begin(9600); 
// 開啟 Serial port, 通訊速率為 9600 bps 
 irrecv.enableIRIn(); 
// 啟動紅外線解碼 
} 
// 顯示紅外線協定種類 
void showIRProtocol(decode_results *results) 
{ 
 Serial.print("Protocol: "); 
 // 判斷紅外線協定種類 
 switch(results->decode_type) 
 { 
 case NEC: 
 Serial.print("NEC"); 
 break; 
 case SONY: 
 Serial.print("SONY"); 
 break; 
 case RC5: 
 Serial.print("RC5"); 
 break; 
 case RC6: 
 Serial.print("RC6"); 
 break; 
 default: 
 Serial.print("Unknown encoding"); 
 } 
// 把紅外線編碼印到 Serial port 
 Serial.print(", irCode: "); 
 Serial.print(results->value, HEX); 
// 紅外線編碼 
 Serial.print(", bits: "); 
 Serial.println(results->bits); 
// 紅外線編碼位元數 
} 
void loop() 
{ 
 if (irrecv.decode(&results)) { 
// 解碼成功，收到一組紅外線訊號 
 showIRProtocol(&results); 
// 顯示紅外線協定種類 
 irrecv.resume(); 
// 繼續收下一組紅外線訊號
 } 
}

紅外線遙控電器用品 

#include <IRremote.h> 
 // 引用 IRRemote 函式庫 
const int irReceiverPin = 2; 
// 紅外線接收器 OUTPUT 訊號接在 pin 2 
IRrecv irrecv(irReceiverPin); // 定義 IRrecv 物件來接收紅外線訊號 
decode_results results; 
// 解碼結果將放在 decode_results 結構的 result 變數裏 
void setup() 
{ 
 Serial.begin(9600); 
// 開啟 Serial port, 通訊速率為 9600 bps 
 pinMode(13, OUTPUT); 
// 宣告 pin 13 為輸出 
 irrecv.enableIRIn(); 
// 啟動接收 
} 
void loop() 
{ 
 if (irrecv.decode(&results)) 
// 接收紅外線訊號並解碼 
 { 
 if ((results.value == 0xFF58A7) || (results.value == 0xDC0197DB)) //接收到遙控器訊號 
 { 
if (digitalRead(13) == LOW) // 讀取 pin 13 狀態 
digitalWrite(13 , HIGH); 
// 指示燈開 
else 
digitalWrite(13 , LOW); 
// 指示燈關 
delay(10); 
 } 
 irrecv.resume(); // 準備接收下一個訊號 
 } 
} 

研究六：利用Arduino 及紅外線發射38KHz 製作警戒系統 
我們利用紅外線38KHz 製作警戒線，減少光線干擾。 
紅外線發射線路圖： 

紅外線發射Arduino 程式： 
#include <IRremote.h> 
IRsend irsend; 
void setup() 
{ 
 Serial.begin(9600); // 開啟 Serial port, 通訊速率為 9600 bps 
} 
void loop() 
{ 
 irsend.sendNEC(0x1FFFFFF, 32); // 發射紅外線訊號 
 delay(10); 
} 

紅外線接收線路圖： 

紅外線接收Arduino 程式： 
#include <IRremote.h> // 引用 IRRemote 函式庫 
const int irReceiver = 2; // 紅外線接收器 
const int ledPin = 13; // 揚聲器 
int countnum; 
int i; 
void setup() 
{ 
 Serial.begin(9600); 
// 開啟 Serial port, 通訊速率為 9600 bps 
 pinMode(irReceiver, INPUT); 
// 把 irReceiver 接腳設置為 INPUT 
 pinMode(ledPin, OUTPUT); // 把 ledPin 設置為 OUTPUT 
 countnum = 0; 
} 
void loop() 
{ 
 int ir_status = digitalRead(irReceiver); 
// 讀取 irReceiver 的狀態 
 Serial.println(ir_status); // 把 irReceiver 的狀態印到 Serial Port 
 // 檢查 irReceiver 是否有收到紅外線訊號 
 // 有的話，ir_status 會是 0 (因為 Receiver 會把訊號反向, 所以 0 代表有收到訊號) 
 if (ir_status == 0) 
 { 
 digitalWrite(ledPin, LOW); // 關掉揚聲器 
 countnum = 0; 
 } 
 if (ir_status == 1) 
 { 
 countnum++; 
 if (countnum >= 20) 
 { 
digitalWrite(ledPin,HIGH); 
//打開揚聲器 
delay(100); 
digitalWrite(ledPin,LOW); 
//關閉揚聲器 
delay(100); 
countnum = 20; 
 } 
 } 
}
